<?php declare(strict_types=1); $this->layout('layouts/default',['title'=>$title,'currentPage'=>'proposals']); $statuses=['new'=>'Nova','contacted'=>'Contatada','qualified'=>'Qualificada','won'=>'Convertida','lost'=>'Perdida','archived'=>'Arquivada']; ?>
<section class="studio-page"><header class="studio-page-heading"><div><p class="studio-eyebrow">COMERCIAL</p><h2>Propostas</h2><p>Pipeline, histórico e respostas das solicitações recebidas.</p></div></header>
<form class="studio-filter-bar" method="get"><label><span>Busca</span><input name="q" value="<?= $this->e($search) ?>" placeholder="Nome, e-mail ou empresa"></label><label><span>Status</span><select name="status"><option value="">Todos</option><?php foreach($statuses as $value=>$label):?><option value="<?= $value ?>"<?= $status===$value?' selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label><button>Filtrar</button><a href="/admin/proposals">Limpar</a></form>
<div class="studio-table-wrap"><table><thead><tr><th>Contato</th><th>Serviço</th><th>Status</th><th>Responsável</th><th>Histórico</th><th></th></tr></thead><tbody><?php if($records===[]):?><tr><td colspan="6" class="studio-empty">Nenhuma proposta recebida.</td></tr><?php endif;?><?php foreach($records as $record):?><tr><td><strong><?= $this->e($record['name']) ?></strong><small><?= $this->e($record['email']) ?><?= $record['company']?' · '.$this->e($record['company']):'' ?></small></td><td><?= $this->e($record['service']) ?></td><td><span class="studio-status"><?= $this->e($statuses[$record['status']]??$record['status']) ?></span></td><td><?= $this->e($record['assignee_name']??'Não atribuído') ?></td><td><?= (int)$record['history_count'] ?></td><td><a href="?view=<?= (int)$record['id'] ?>">Abrir</a></td></tr><?php endforeach;?></tbody></table></div>
<?php if($selected):?><section class="studio-proposal-detail"><article class="studio-panel"><p class="studio-eyebrow">PROPOSTA #<?= (int)$selected['id'] ?></p><h2><?= $this->e($selected['name']) ?></h2><p><?= nl2br($this->e($selected['message'])) ?></p><dl><dt>E-mail</dt><dd><?= $this->e($selected['email']) ?></dd><dt>Serviço</dt><dd><?= $this->e($selected['service']) ?></dd></dl><form method="post"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$selected['id'] ?>"><input type="hidden" name="action" value="status"><label><span>Status</span><select name="status"><?php foreach($statuses as $value=>$label):?><option value="<?= $value ?>"<?= $selected['status']===$value?' selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label><label><span>Observação opcional</span><input name="note" maxlength="5000"></label><button>Atualizar status</button></form><form method="post"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$selected['id'] ?>"><input type="hidden" name="action" value="respond"><label><span>Resposta</span><textarea name="note" minlength="10" maxlength="5000" required><?= $this->e($selected['response']??'') ?></textarea></label><button>Registrar resposta</button></form><form method="post"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$selected['id'] ?>"><button name="action" value="convert">Converter proposta</button></form></article><article class="studio-panel"><h2>Histórico</h2><form method="post"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$selected['id'] ?>"><input type="hidden" name="action" value="note"><label><span>Nova observação</span><textarea name="note" minlength="2" maxlength="5000" required></textarea></label><button>Adicionar</button></form><ol class="studio-history"><?php foreach($history as $item):?><li><strong><?= $this->e($item['action']) ?></strong><p><?= $this->e($item['note']??'') ?></p><small><?= $this->e($item['author_name']??'Sistema') ?> · <?= $this->e($item['created_at']) ?></small></li><?php endforeach;?></ol></article></section><?php endif;?></section>
